mapper.select:


    inner join sys_user u on u.user_name = tmovelibrary.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tmovelibrary.del_flag = '0'
     and tmovelibrary.code like concat('%', #{code}, '%')
     and tmovelibrary.location_out_id = #{locationOutId}
     and tmovelibrary.location_in_id = #{locationInId}
     and tmovelibrary.tray_id = #{trayId}
     and tmovelibrary.status = #{status}
     and tmovelibrary.auditor_status = #{auditorStatus}
     and tmovelibrary.auditor = #{auditor}
     and tmovelibrary.auditor_name like concat('%', #{auditorName}, '%')


${params.dataScope}

select distinct l.id, l.code, l.dept_id, l.dept_name, l.location_out_id, l.location_in_id, l.tray_id, l.status, l.auditor_status, l.auditor, l.auditor_name, l.create_by, l.create_time, l.update_by, l.update_time, l.remark, l.del_flag from t_move_library as l left join t_move_library_detail as d on l.code = d.move_library_code and d.del_flag = '0'
l.del_flag = '0' and l.code = #{moveLibrary.code} and l.dept_id = #{moveLibrary.deptId} and l.status = #{moveLibrary.status} and l.auditor_status = #{moveLibrary.auditorStatus}
and d.material_id in
#{materialId}
order by l.create_time desc, l.id desc
